parameters.text:
=Analise a seguinte solicitação de atendimento e retorne EXCLUSIVAMENTE um objeto JSON válido (sem blocos markdown) contendo as chaves "categoria", "prioridade", "resumo" e "justificativa".

Solicitante: {{ $json.solicitante }}
Assunto: {{ $json.assunto }}
Prioridade informada pelo usuário: {{ $json.prioridade_informada }}
Mensagem: {{ $json.mensagem }}

parameters.jsCode:
const entrada = $('Normalizar Dados de Entrada').item.json;
const respostaBrutaIA = $input.first()?.json?.output ?? $input.first()?.json?.text ?? null;

const CATEGORIAS_PERMITIDAS = ['Comercial', 'Suporte técnico', 'Financeiro', 'Outros'];
const PRIORIDADES_PERMITIDAS = ['Alta', 'Média', 'Baixa'];

let resultadoIA = null;
let statusValidacao = 'validado_fallback_regras';
let modoExecucao = 'simulacao_demonstrativa_local';

if (typeof respostaBrutaIA === 'string' && respostaBrutaIA.trim().length > 0) {
  try {
    const limpo = respostaBrutaIA.replace(/```json|```/gi, '').trim();
    const parsed = JSON.parse(limpo);
    if (
      CATEGORIAS_PERMITIDAS.includes(parsed.categoria) &&
      PRIORIDADES_PERMITIDAS.includes(parsed.prioridade) &&
      parsed.resumo &&
      parsed.justificativa
    ) {
      resultadoIA = parsed;
      statusValidacao = 'validado_ia';
      modoExecucao = 'ia_ativa_validada';
    }
  } catch (e) {
    resultadoIA = null;
  }
}

if (!resultadoIA) {
  const texto = `${entrada.assunto} ${entrada.mensagem}`.toLowerCase();
  let categoria = 'Outros';
  let prioridade = 'Baixa';
  let justificativa = 'Solicitação fora do escopo principal ou sem palavras-chave críticas identificadas; encaminhada para análise geral.';

  if (/(erro|bug|fora do ar|caiu|falha|webhook|api|timeout|indispon|suporte|travando)/.test(texto)) {
    categoria = 'Suporte técnico';
    prioridade = /(urgente|crítico|critico|fora do ar|caiu|produção|producao|alta)/.test(texto + ' ' + entrada.prioridade_informada.toLowerCase()) ? 'Alta' : 'Média';
    justificativa = 'Identificados termos técnicos de incidente ou falha operacional que requerem atuação da equipe de suporte.';
  } else if (/(boleto|fatura|nota fiscal|cobrança|cobranca|pagamento|reembolso|pix|assinatura)/.test(texto)) {
    categoria = 'Financeiro';
    prioridade = /(vencido|bloqueio|duplicado|urgente|alta)/.test(texto) ? 'Alta' : 'Média';
    justificativa = 'Identificados termos financeiros relativos a faturamento, cobrança ou pagamento.';
  } else if (/(orçamento|orcamento|proposta|plano|contratar|licença|licenca|demonstração|demonstracao|preço|preco|comercial)/.test(texto)) {
    categoria = 'Comercial';
    prioridade = 'Média';
    justificativa = 'Identificada intenção de compra, cotação de planos ou demonstração comercial.';
  }

  const resumoBase = entrada.mensagem.length > 140 ? entrada.mensagem.substring(0, 137) + '...' : entrada.mensagem;
  resultadoIA = {
    categoria,
    prioridade,
    resumo: resumoBase,
    justificativa
  };
}

return [
  {
    json: {
      protocolo: entrada.protocolo,
      solicitante: entrada.solicitante,
      email: entrada.email,
      assunto: entrada.assunto,
      categoria: resultadoIA.categoria,
      prioridade: resultadoIA.prioridade,
      resumo: resultadoIA.resumo,
      justificativa: resultadoIA.justificativa,
      status_validacao: statusValidacao,
      modo_execucao: modoExecucao,
      processado_em: new Date().toISOString()
    }
  }
];

